-- Sprint F1 step 2: foundations schema, part 1 of 8.
--
-- pg_trgm backs the trigram matching index on elements_head (SPEC-data-model.md
-- §3.5, §8) used by the capture pipeline's name+context matching. Nothing else
-- in this sprint needs an extension: ids are minted by the writer (SPEC §2,
-- S-1), not generated by the database, so pgcrypto/gen_random_uuid() is not
-- part of the application's write path. The one exception — the `main`
-- branch row the database creates as a side effect of a model being
-- created — uses gen_random_uuid(), which Postgres 13+ provides natively.
create extension if not exists pg_trgm;

-- Namespace for helper functions and (in later steps) security-definer
-- procedures, kept separate from the table-bearing public schema per
-- SPEC-data-model.md §2.
create schema if not exists atlas;

comment on schema atlas is
  'Helper functions and procedures for RLS and engine operations. Tables live in public; atlas holds behaviour.';
